package io.github.headlesshq.headlessmc.plugins;

import io.github.headlesshq.headlessmc.reflection.ReflectionRegistered;
import io.quarkus.runtime.annotations.RegisterForReflection;
import org.jspecify.annotations.Nullable;

import java.util.List;
import java.util.Objects;

/**
 * The manifest every plugin jar contains at {@value #PATH}.
 * It is generated by the HeadlessMc plugin Gradle template.
 *
 * @param schemaVersion the version of this format, currently {@value #SCHEMA_VERSION}.
 * @param id            the unique id of the plugin, lowercase letters, digits, {@code -} and {@code _}.
 * @param version       the version of the plugin.
 * @param name          a human-readable name.
 * @param description   a short description.
 * @param authors       the authors.
 * @param license       the license, preferably an SPDX identifier.
 * @param homepage      a link to the homepage or source code.
 * @param headlessmc    the {@link io.github.headlesshq.headlessmc.plugins.version.VersionRange}
 *                      of HeadlessMc versions the plugin is compatible with.
 * @param java          the minimum Java version the plugin needs.
 * @param dependencies  other plugins this plugin depends on.
 * @param libraries     the libraries nested in the plugin jar.
 */
@RegisterForReflection
public record PluginManifest(
    int schemaVersion,
    String id,
    String version,
    @Nullable String name,
    @Nullable String description,
    @Nullable List<String> authors,
    @Nullable String license,
    @Nullable String homepage,
    String headlessmc,
    @Nullable Integer java,
    @Nullable List<Dependency> dependencies,
    @Nullable List<Library> libraries
) implements ReflectionRegistered {
    /**
     * The path of the manifest inside a plugin jar.
     */
    public static final String PATH = "META-INF/headlessmc-plugin.json";

    /**
     * The supported {@link #schemaVersion()}.
     */
    public static final int SCHEMA_VERSION = 1;

    /**
     * @return {@link #name()}, or {@link #id()} if no name has been given.
     */
    public String displayName() {
        return Objects.requireNonNullElse(name, id);
    }

    /**
     * @return {@link #dependencies()}, or an empty list.
     */
    public List<Dependency> dependencyList() {
        return Objects.requireNonNullElse(dependencies, List.of());
    }

    /**
     * @return {@link #libraries()}, or an empty list.
     */
    public List<Library> libraryList() {
        return Objects.requireNonNullElse(libraries, List.of());
    }

    /**
     * A dependency on another plugin.
     *
     * @param id       the id of the other plugin.
     * @param versions the range of versions of the other plugin this plugin is compatible with.
     * @param optional if {@code true}, the other plugin does not need to be installed.
     */
    @RegisterForReflection
    public record Dependency(String id, String versions, boolean optional) implements ReflectionRegistered {

    }

    /**
     * A library jar nested in the plugin jar (Jar-in-Jar).
     * If multiple plugins ship the same library, the highest version contained in every
     * {@link #versions()} range is used. If HeadlessMc itself contains the library,
     * its version is used and has to be contained in the range.
     *
     * @param group    the Maven group id.
     * @param artifact the Maven artifact id.
     * @param version  the version of the nested jar.
     * @param versions the range of versions the plugin is compatible with,
     *                 if {@code null}: {@code [version, nextMajor)}.
     * @param path     the path of the nested jar inside the plugin jar, e.g. {@code META-INF/jars/foo-1.0.jar}.
     * @param sha256   the SHA-256 hash of the nested jar.
     */
    @RegisterForReflection
    public record Library(
        String group,
        String artifact,
        String version,
        @Nullable String versions,
        String path,
        String sha256
    ) implements ReflectionRegistered {
        /**
         * @return {@code group:artifact}.
         */
        public String module() {
            return group + ":" + artifact;
        }

    }

}
